#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <getopt.h>

void print_version() {
    printf("samtools be7a51c\n");
    printf("Using htslib 1.23.1\n");
    printf("Copyright (C) 2025 Genome Research Ltd.\n\n");
    printf("Samtools compilation details:\n");
    printf("    Features:       build=configure curses=yes \n");
    printf("    CC:             gcc\n");
    printf("    CPPFLAGS:       \n");
    printf("    CFLAGS:         -Wall -g -O2\n");
    printf("    LDFLAGS:        \n");
    printf("    HTSDIR:         htslib\n");
    printf("    LIBS:           \n");
    printf("    CURSES_LIB:     -lncursesw\n\n");
    printf("HTSlib compilation details:\n");
    printf("    Features:       build=Makefile libcurl=yes S3=no GCS=no libdeflate=no lzma=yes bzip2=yes plugins=no htscodecs=1.6.6\n");
    printf("    CC:             gcc\n");
    printf("    CPPFLAGS:       \n");
    printf("    CFLAGS:         -g -Wall -O2 -fvisibility=hidden\n");
    printf("    LDFLAGS:        -fvisibility=hidden\n\n");
    printf("HTSlib URL scheme handlers present:\n");
    printf("    built-in:\t file, preload, data\n");
    printf("    libcurl:\t gophers, smtp, ldaps, smb, rtsp, tftp, pop3, smbs, imaps, pop3s, ftps, https, http, ftp, gopher, imap, sftp, ldap, smtps, scp, dict, mqtt, telnet, rtmp\n");
    printf("    crypt4gh-needed:\t crypt4gh\n");
    printf("    mem:\t mem\n");
}

void flags_help() {
    printf("About: Convert between textual and numeric flag representation\n");
    printf("Usage: samtools flags FLAGS...\n\n");
    printf("Each FLAGS argument is either an INT (in decimal/hexadecimal/octal) representing\n");
    printf("a combination of the following numeric flag values, or a comma-separated string\n");
    printf("NAME,...,NAME representing a combination of the following flag names:\n\n");
    printf("   0x1     1  PAIRED         paired-end / multiple-segment sequencing technology\n");
    printf("   0x2     2  PROPER_PAIR    each segment properly aligned according to aligner\n");
    printf("   0x4     4  UNMAP          segment unmapped\n");
    printf("   0x8     8  MUNMAP         next segment in the template unmapped\n");
    printf("  0x10    16  REVERSE        SEQ is reverse complemented\n");
    printf("  0x20    32  MREVERSE       SEQ of next segment in template is rev.complemented\n");
    printf("  0x40    64  READ1          the first segment in the template\n");
    printf("  0x80   128  READ2          the last segment in the template\n");
    printf(" 0x100   256  SECONDARY      secondary alignment\n");
    printf(" 0x200   512  QCFAIL         not passing quality controls or other filters\n");
    printf(" 0x400  1024  DUP            PCR or optical duplicate\n");
    printf(" 0x800  2048  SUPPLEMENTARY  supplementary alignment\n");
}

const char *flag_names[] = {
    "PAIRED", "PROPER_PAIR", "UNMAP", "MUNMAP",
    "REVERSE", "MREVERSE", "READ1", "READ2",
    "SECONDARY", "QCFAIL", "DUP", "SUPPLEMENTARY"
};

int flag_values[] = {
    0x1, 0x2, 0x4, 0x8, 0x10, 0x20, 0x40, 0x80, 0x100, 0x200, 0x400, 0x800
};

int parse_flag_str(const char *str) {
    int res = 0;
    char *copy = strdup(str);
    char *token = strtok(copy, ",");
    while (token) {
        int found = 0;
        for (int i = 0; i < 12; i++) {
            if (strcasecmp(token, flag_names[i]) == 0) {
                res |= flag_values[i];
                found = 1;
                break;
            }
        }
        if (!found) {
            free(copy);
            return -1;
        }
        token = strtok(NULL, ",");
    }
    free(copy);
    return res;
}

void print_flags_val(int flags) {
    printf("0x%x\t%d\t", flags, flags);
    int first = 1;
    for (int i = 0; i < 12; i++) {
        if (flags & flag_values[i]) {
            if (!first) printf(",");
            printf("%s", flag_names[i]);
            first = 0;
        }
    }
    printf("\n");
}

int main_flags(int argc, char *argv[]) {
    if (argc < 1) {
        flags_help();
        return 0;
    }
    if (strcmp(argv[0], "--help") == 0 || strcmp(argv[0], "-?") == 0) {
        flags_help();
        return 0;
    }
    for (int i = 0; i < argc; i++) {
        int val;
        if (isdigit(argv[i][0])) {
            val = (int)strtol(argv[i], NULL, 0);
        } else {
            val = parse_flag_str(argv[i]);
            if (val == -1) {
                fprintf(stderr, "samtools flags: Could not parse \"%s\"\n", argv[i]);
                flags_help();
                return 1;
            }
        }
        print_flags_val(val);
    }
    return 0;
}

void print_general_help() {
    fprintf(stderr, "\nProgram: samtools (Tools for alignments in the SAM format)\n");
    fprintf(stderr, "Version: be7a51c (using htslib 1.23.1)\n\n");
    fprintf(stderr, "Usage:   samtools <command> [options]\n\n");
    fprintf(stderr, "Commands:\n");
    fprintf(stderr, "  -- Indexing\n");
    fprintf(stderr, "     dict           create a sequence dictionary file\n");
    fprintf(stderr, "     faidx          index/extract FASTA\n");
    fprintf(stderr, "     fqidx          index/extract FASTQ\n");
    fprintf(stderr, "     index          index alignment\n\n");
    fprintf(stderr, "  -- Editing\n");
    fprintf(stderr, "     calmd          recalculate MD/NM tags and '=' bases\n");
    fprintf(stderr, "     fixmate        fix mate information\n");
    fprintf(stderr, "     reheader       replace BAM header\n");
    fprintf(stderr, "     targetcut      cut fosmid regions (for fosmid pool only)\n");
    fprintf(stderr, "     addreplacerg   adds or replaces RG tags\n");
    fprintf(stderr, "     markdup        mark duplicates\n");
    fprintf(stderr, "     ampliconclip   clip oligos from the end of reads\n\n");
    fprintf(stderr, "  -- File operations\n");
    fprintf(stderr, "     collate        shuffle and group alignments by name\n");
    fprintf(stderr, "     cat            concatenate BAMs\n");
    fprintf(stderr, "     consensus      produce a consensus Pileup/FASTA/FASTQ\n");
    fprintf(stderr, "     merge          merge sorted alignments\n");
    fprintf(stderr, "     mpileup        multi-way pileup\n");
    fprintf(stderr, "     sort           sort alignment file\n");
    fprintf(stderr, "     split          splits a file by read group\n");
    fprintf(stderr, "     quickcheck     quickly check if SAM/BAM/CRAM file appears intact\n");
    fprintf(stderr, "     fastq          converts a BAM to a FASTQ\n");
    fprintf(stderr, "     fasta          converts a BAM to a FASTA\n");
    fprintf(stderr, "     import         Converts FASTA or FASTQ files to SAM/BAM/CRAM\n");
    fprintf(stderr, "     reference      Generates a reference from aligned data\n");
    fprintf(stderr, "     reset          Reverts aligner changes in reads\n\n");
    fprintf(stderr, "  -- Statistics\n");
    fprintf(stderr, "     bedcov         read depth per BED region\n");
    fprintf(stderr, "     coverage       alignment depth and percent coverage\n");
    fprintf(stderr, "     depth          compute the depth\n");
    fprintf(stderr, "     flagstat       simple stats\n");
    fprintf(stderr, "     idxstats       BAM index stats\n");
    fprintf(stderr, "     cram-size      list CRAM Content-ID and Data-Series sizes\n");
    fprintf(stderr, "     phase          phase heterozygotes\n");
    fprintf(stderr, "     stats          generate stats (former bamcheck)\n");
    fprintf(stderr, "     ampliconstats  generate amplicon specific stats\n");
    fprintf(stderr, "     checksum       produce order-agnostic checksums of sequence content\n\n");
    fprintf(stderr, "  -- Viewing\n");
    fprintf(stderr, "     flags          explain BAM flags\n");
    fprintf(stderr, "     head           header viewer\n");
    fprintf(stderr, "     tview          text alignment viewer\n");
    fprintf(stderr, "     view           SAM<->BAM<->CRAM conversion\n");
    fprintf(stderr, "     depad          convert padded BAM to unpadded BAM\n");
    fprintf(stderr, "     samples        list the samples in a set of SAM/BAM/CRAM files\n\n");
    fprintf(stderr, "  -- Misc\n");
    fprintf(stderr, "     help [cmd]     display this help message or help for [cmd]\n");
    fprintf(stderr, "     version        detailed version information\n\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_general_help();
        return 1;
    }
    if (strcmp(argv[1], "version") == 0) {
        print_version();
        return 0;
    }
    if (strcmp(argv[1], "flags") == 0) {
        return main_flags(argc - 2, argv + 2);
    }
    if (strcmp(argv[1], "help") == 0) {
