int main_view(int argc, char *argv[]) {
    int with_header = 0, header_only = 0; char *out_fn = NULL, *fai_ref = NULL;
    int opt; optind = 0;
    while ((opt = getopt(argc, argv, "hHo:t:Sb")) != -1) {
        if (opt == 'h') with_header = 1; else if (opt == 'H') header_only = 1;
        else if (opt == 'o') out_fn = optarg; else if (opt == 't') fai_ref = optarg;
    }
    if (optind >= argc) { fprintf(stderr, "[main_samview] fail to read the header from \"-\".\n"); return 1; }
    char *in_fn = argv[optind];
    gzFile in = gzopen(in_fn, "r"); if (!in) return 1;
    FILE *out = out_fn ? fopen(out_fn, "w") : stdout;
    if (fai_ref) {
        FILE *f = fopen(fai_ref, "r"); if (f) {
            char l[1024]; while (fgets(l, sizeof(l), f)) { char n[1024]; long len; sscanf(l, "%s %ld", n, &len); fprintf(out, "@SQ\tSN:%s\tLN:%ld\n", n, len); }
            fclose(f);
        }
    }
    char buf[65536]; int header_printed = 0;
    while (gzgets(in, buf, sizeof(buf))) {
        if (buf[0] == '@') { if (with_header || header_only) fputs(buf, out); }
        else {
            if (header_only) break;
            if (!header_printed) {
                if (with_header) {
                    fprintf(out, "@PG\tID:samtools\tPN:samtools\tVN:%s\tCL:./executable view", VERSION);
                    for (int i=0; i<argc; i++) fprintf(out, " %s", argv[i]);
                    fprintf(out, "\n");
                }
                header_printed = 1;
            }
            char *p = buf; for (int i=0; i<9 && p; i++) p = strchr(p+1, '\t');
            if (p) { p++; while (*p && *p != '\t') { *p = toupper(*p); p++; } }
            fputs(buf, out);
        }
    }
    if (header_only && !header_printed && with_header) {
        fprintf(out, "@PG\tID:samtools\tPN:samtools\tVN:%s\tCL:./executable view", VERSION);
        for (int i=0; i<argc; i++) fprintf(out, " %s", argv[i]);
        fprintf(out, "\n");
    }
    gzclose(in); if (out_fn) fclose(out); return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) { print_general_help(); return 1; }
    if (strcmp(argv[1], "version") == 0) { print_version(); return 0; }
    if (strcmp(argv[1], "flags") == 0) return main_flags(argc-2, argv+2);
    if (strcmp(argv[1], "faidx") == 0) return main_faidx(argc-2, argv+2);
    if (strcmp(argv[1], "view") == 0) return main_view(argc-2, argv+2);
    if (strcmp(argv[1], "help") == 0) {
        if (argc == 2) { print_general_help(); return 0; }
        if (strcmp(argv[2], "flags") == 0) { print_flags_help(); return 0; }
        print_general_help(); return 0;
    }
    fprintf(stderr, "[main] unrecognized command '%s'\n", argv[1]); return 1;
}
